}

{
  "sql": "SELECT SUM(amount) AS value FROM ledger WHERE account_group = 'Revenue' AND month >= '2026-01' AND month <= '2026-09'",
  "explanation": "The request asks for revenue in 2026. Since the data coverage ends in September 2026, this query sums all revenue amounts from January 2026 through September 2026."
}

{
  "sql": "SELECT SUM(amount) AS value FROM ledger WHERE account_group = 'Revenue' AND month BETWEEN '2026-01' AND '2026-03'",
  "explanation": "Sums all revenue amounts for the first quarter of 2026 (January through March) across all entities."
}

{
  "sql": "SELECT SUM(CASE WHEN account_group = 'Revenue' THEN amount ELSE 0 END) - SUM(CASE WHEN account_group = 'Cost of sales' THEN amount ELSE 0 END) AS value FROM ledger WHERE month BETWEEN '2025-10' AND '2025-12'",
  "explanation": "Calculates gross profit for Q4 2025 by summing revenue and subtracting cost of sales for the months October, November, and December 2025."
}

{
  "sql": "SELECT ROUND(100.0 * (SUM(CASE WHEN account_group = 'Revenue' THEN amount ELSE 0 END) - SUM(CASE WHEN account_group = 'Cost of sales' THEN amount ELSE 0 END)) / NULLIF(SUM(CASE WHEN account_group = 'Revenue' THEN amount ELSE 0 END), 0), 1) AS value FROM ledger WHERE month LIKE '2025-%'",
  "explanation": "Calculates the gross margin for the full year 2025 by summing all revenue and cost of sales amounts for that period and applying the standard margin formula."
}

{
  "sql": "SELECT SUM(CASE WHEN account_group = 'Revenue' THEN amount ELSE 0 END) - SUM(CASE WHEN account_group = 'Cost of sales' THEN amount ELSE 0 END) - SUM(CASE WHEN account_group = 'Operating expense' THEN amount ELSE 0 END) AS value FROM ledger WHERE month >= '2026-01' AND month <= '2026-09'",
  "explanation": "Calculates operating profit for the available year-to-date period in 2026 (January through September) by summing revenue, subtracting cost of sales and operating expenses."
}

{
  "sql": "SELECT SUM(amount) AS value FROM ledger WHERE account_group = 'Operating expense' AND month = '2026-03'",
