}

{
  "sql": "SELECT entity AS label, SUM(amount) AS value FROM ledger WHERE account_group = 'Revenue' AND month BETWEEN '2025-01' AND '2025-12' GROUP BY entity ORDER BY label ASC",
  "explanation": "The query sums all revenue amounts for each entity for the full year 2025, grouping by entity and ordering the results alphabetically."
}

{
  "sql": "SELECT entity AS label, SUM(CASE WHEN account_group = 'Revenue' THEN amount ELSE 0 END) - SUM(CASE WHEN account_group = 'Cost of sales' THEN amount ELSE 0 END) - SUM(CASE WHEN account_group = 'Operating expense' THEN amount ELSE 0 END) AS value FROM ledger WHERE month IN ('2026-07', '2026-08', '2026-09') GROUP BY entity ORDER BY value DESC, label ASC LIMIT 100",
  "explanation": "Calculates operating profit for each entity in Q3 2026 (July-September) by summing revenue, subtracting cost of sales and operating expenses, and grouping by entity."
}

{
  "sql": "SELECT month, SUM(amount) AS value FROM ledger WHERE account_group = 'Revenue' AND month BETWEEN '2025-01' AND '2025-12' GROUP BY month ORDER BY month",
