}

{
  "sql": "SELECT strftime('%Y', month) || '-Q' || CAST((CAST(strftime('%m', month) AS INTEGER) - 1) / 3 + 1 AS TEXT) AS label, SUM(amount) AS value FROM ledger WHERE account_group = 'Revenue' AND month BETWEEN '2025-01' AND '2025-12' GROUP BY label ORDER BY label",
  "explanation": "Aggregates revenue by calendar quarter for the full year 2025, which is fully covered by the available data."
}

{
